namespace sv_fc273f3b31ed4e09b52d93df0d88cbfc.Services;

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single user circuit.
/// Components subscribe to OnChange to react when the warehouse selection changes.
/// </summary>
public class WarehouseState
{
    public static readonly IReadOnlyList<WarehouseInfo> AvailableWarehouses =
    [
        new("wh-1", "Warehouse A — East"),
        new("wh-2", "Warehouse B — West"),
        new("wh-3", "Warehouse C — Central"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name ?? "Unknown";

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

public record WarehouseInfo(string Id, string Name);

namespace sv_fc273f3b31ed4e09b52d93df0d88cbfc.Services;

/// <summary>
/// Simulates a database query that returns the number of low-stock items for a warehouse.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async database call with random result 0–15
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }
}

namespace sv_fc273f3b31ed4e09b52d93df0d88cbfc.Services;

/// <summary>
/// Scoped service that manages low-stock alert polling for the current user circuit.
/// Polling is reference-counted: starts when the first subscriber requests it, stops
/// when the last subscriber releases it. All subscribers are notified when new data arrives.
/// </summary>
public class InventoryAlertState : IDisposable
{
    private readonly InventoryAlertService _alertService;
    private readonly WarehouseState _warehouseState;
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentLowStockCount { get; private set; }

    /// <summary>
    /// Fired when polling retrieves new data. All subscribed components should re-render.
    /// </summary>
    public event Action? OnChange;

    public InventoryAlertState(InventoryAlertService alertService, WarehouseState warehouseState)
    {
        _alertService = alertService;
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    /// <summary>
    /// Call when a component wants polling to be active (e.g., dashboard is visible).
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    /// <summary>
    /// Call when a component no longer needs polling (e.g., user leaves page).
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            CancelTimer();
        }
    }

    /// <summary>
    /// Immediately refresh the alert count (e.g., after warehouse change).
    /// </summary>
    public async Task RefreshAsync()
    {
        CurrentLowStockCount = await _alertService.GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        OnChange?.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken cancellationToken)
    {
        // Fire immediately on start
        await RefreshAsync();

        while (_timer is not null && !cancellationToken.IsCancellationRequested)
        {
            try
            {
                if (!await _timer.WaitForNextTickAsync(cancellationToken))
                    break;
                await RefreshAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private void OnWarehouseChanged()
    {
        // When the warehouse changes, immediately refresh if polling is active
        if (_subscriberCount > 0)
        {
            _ = RefreshAsync();
        }
    }

    private void CancelTimer()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        CancelTimer();
    }
}

